"use strict";
// Functions declared inside functions and loops: each time the declaration
// runs it makes a new function, with its own properties.

function show(dial, amount) {
  return dial.unit + ":" + amount;
}

// The function hands itself to a helper.
function makeDial(unit) {
  const dial = (amount) => show(dial, amount);
  dial.unit = unit;
  return dial;
}

// A function expression that keeps a total on itself.
function makeCounter() {
  const count = function (step) {
    count.total = (count.total || 0) + step;
    return count.total;
  };
  return count;
}
function totalOf(count) {
  return count.total;
}

// A function expression that hands itself on under its own name.
function makeEcho(unit) {
  const echo = function self(amount) {
    return show(self, amount);
  };
  echo.unit = unit;
  return echo;
}

// The function never mentions itself; the caller writes a property on it.
function makeLabel(text) {
  const label = (suffix) => "label" + suffix;
  label.text = text;
  return label;
}

// No property at all: only the identity tells two of them apart.
function pass(next, depth) {
  return next(depth);
}
function makeRelay() {
  const relay = (depth) => (depth > 2 ? depth : pass(relay, depth + 1));
  return relay;
}

// One declaration in a loop.
function makeSteps(count) {
  const steps = [];
  for (let i = 0; i < count; i++) {
    const step = (value) => value + 1;
    steps.push(step);
  }
  return steps;
}

// A helper that is only ever called has no identity to tell.
function area(width, height) {
  const double = (value) => value * 2;
  return double(width) * double(height);
}

// Declared once, at the top of the module: one function for the program.
const shared = (amount) => show(shared, amount);
shared.unit = "shared";
function getShared() {
  return shared;
}

module.exports = {
  makeDial,
  makeCounter,
  totalOf,
  makeEcho,
  makeLabel,
  makeRelay,
  makeSteps,
  area,
  shared,
  getShared,
};
